const wc = $('When Called').first().json;
let raw = String(wc.output_message || '').trim();
const parse_warnings = [];
// Strip a ```json ... ``` (or bare ```) fence if the agent wrapped the array in one (observed live, 5.3).
const fence = raw.match(/^```[a-zA-Z]*\s*([\s\S]*?)\s*```\s*$/);
if (fence) raw = fence[1].trim();
let blocks = null;
try { blocks = JSON.parse(raw); } catch (e) {}
if (blocks && !Array.isArray(blocks) && Array.isArray(blocks.blocks)) blocks = blocks.blocks;
if (!Array.isArray(blocks)) {
  parse_warnings.push({ source: 'output-adapter/parse-fallback', err: 'output_message nie jest tablica blokow JSON — dostarczono jako zwykly tekst', severity: 'WARN' });
  blocks = [{ type: 'text', md: String(wc.output_message || '') }];
}
const assembly = [];
const images = [];
let genIdx = 0;
for (let i = 0; i < blocks.length; i++) {
  const b = blocks[i] || {};
  const order = (b.order != null) ? Number(b.order) : (i + 1);
  if (b.type === 'text') {
    assembly.push({ kind: 'text', order: order, md: (b.md != null ? b.md : (b.text || '')) });
  } else if (b.type === 'image') {
    const ref = String(b.ref || b.file_id || '');
    const pid = 'gen_' + genIdx; genIdx++;
    assembly.push({ kind: 'image', order: order, placeholder_id: pid, caption: b.caption || '', alt: b.alt || '', ref: ref });
    if (ref.indexOf('file_') === 0) {
      images.push({ placeholder_id: pid, file_id: ref, mime: b.mime || 'image/png', caption: b.caption || '', alt: b.alt || '' });
    } else {
      parse_warnings.push({ source: 'output-adapter/image-ref-unrecognized', err: 'blok image ma ref ktory nie jest file_id Files-API: ' + (ref || '(pusty)') + ' — nie mozna dostarczyc obrazu', severity: 'WARN' });
    }
  }
  // other block types (future office-doc/file blocks) are skipped here — Block 7.
}
return [{ json: { assembly: assembly, images: images, parse_warnings: parse_warnings, clickup_task_id: wc.clickup_task_id || '', image_count: images.length } }];

// Read each downloaded image's bytes as base64. Binary is in filesystem mode on this instance,
// so binary.data.data is only the storage marker ('filesystem-v2') -> must use the binary-data helper.
const items = $input.all();
const split = $('Split Out Images').all();
const out = [];
for (let k = 0; k < items.length; k++) {
  let srcIdx = 0;
  const pi = items[k].pairedItem;
  if (pi != null) srcIdx = (typeof pi === 'number') ? pi : (pi.item != null ? pi.item : 0);
  const meta = (split[srcIdx] && split[srcIdx].json) || {};
  let b64 = '';
  try { const buf = await this.helpers.getBinaryDataBuffer(k, 'data'); if (buf) b64 = buf.toString('base64'); } catch (e) {}
  const mime = (items[k].binary && items[k].binary.data && items[k].binary.data.mimeType) || meta.mime || 'image/png';
  if (b64) out.push({ json: { ok: true, placeholder_id: meta.placeholder_id, file_id: meta.file_id, b64: b64, mime: mime, caption: meta.caption || '', alt: meta.alt || '' } });
  else out.push({ json: { ok: false, placeholder_id: meta.placeholder_id, file_id: meta.file_id, warning: 'output-adapter/image-bytes-empty: ' + (meta.file_id || '') + ' pobrano pusta zawartosc z carrier' } });
}
return out;

const rows = $input.all().map(function(i){ return i.json; }).filter(Boolean);
const manifest = [];
const warnings = [];
for (const r of rows) {
  if (r.ok === true && r.b64) manifest.push({ placeholder_id: r.placeholder_id, b64: r.b64, mime: r.mime, caption: r.caption || '', alt: r.alt || '' });
  else if (r.warning) warnings.push({ source: 'output-adapter/image', err: r.warning, severity: 'WARN' });
}
return [{ json: { manifest_json: JSON.stringify(manifest), image_warnings_json: JSON.stringify(warnings) } }];

const inp = ($input.first() && $input.first().json) || {};
let manifest = []; try { manifest = JSON.parse(inp.manifest_json || '[]'); } catch (e) {}
let imageWarnings = []; try { imageWarnings = JSON.parse(inp.image_warnings_json || '[]'); } catch (e) {}
const pb = $('Parse Blocks').first().json;
let assembly = Array.isArray(pb.assembly) ? pb.assembly.slice() : [];
let warnings = Array.isArray(pb.parse_warnings) ? pb.parse_warnings.slice() : [];
warnings = warnings.concat(imageWarnings);
const byPid = {};
for (const e of manifest) { if (e && e.placeholder_id) byPid[e.placeholder_id] = e; }

// --- mdToOps + helpers: copied VERBATIM from Image Resolver (v1) 'Assemble Output' so the ClickUp ops format is identical (Post Reply consumes both lanes' rendered_delta). KEEP IN SYNC if the resolver renderer changes. ---
const FENCE = String.fromCharCode(96, 96, 96);
const LINK = /\[([^\]]+)\]\(([^)]+)\)/;
const BOLD = /\*\*([^*]+)\*\*/;
const CODE = /\x60([^\x60]+)\x60/;
const ITAL = /\*([^*]+)\*|_([^_]+)_/;
function inlineOps(t) {
  const out = [];
  let rest = String(t);
  while (rest.length) {
    let best = null, kind = null;
    const cands = [[LINK,'link'],[BOLD,'bold'],[CODE,'code'],[ITAL,'ital']];
    for (const c of cands) { const m = c[0].exec(rest); if (m && (best === null || m.index < best.index)) { best = m; kind = c[1]; } }
    if (!best) { out.push({ text: rest }); break; }
    if (best.index > 0) out.push({ text: rest.slice(0, best.index) });
    if (kind === 'link') out.push({ text: best[1], attributes: { link: best[2] } });
    else if (kind === 'bold') out.push({ text: best[1], attributes: { bold: true } });
    else if (kind === 'code') out.push({ text: best[1], attributes: { code: true } });
    else out.push({ text: best[1] || best[2], attributes: { italic: true } });
    rest = rest.slice(best.index + best[0].length);
  }
  return out.length ? out : [{ text: '' }];
}
function isRow(s){ const t=s.trim(); return t.length>1 && t.charAt(0)==='|' && t.charAt(t.length-1)==='|'; }
function isSep(s){ const t=s.trim(); return /^[|\s:-]+$/.test(t) && t.indexOf('-')>=0; }
function cellsOf(s){ return s.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(function(c){return c.trim();}); }
function mdToOps(md) {
  const ops = [];
  function emit(inline, attrs) { for (const o of inline) ops.push(o); ops.push(attrs ? { text: '\n', attributes: attrs } : { text: '\n' }); }
  const L = String(md).replace(/\r/g,'').split('\n');
  let i=0, gRow=0, inCode=false;
  while (i < L.length) {
    const s = L[i];
    if (s.trim().indexOf(FENCE) === 0) { inCode = !inCode; i++; continue; }
    if (inCode) { ops.push({ text: s }); ops.push({ text: '\n', attributes: { 'code-block': 'plain' } }); i++; continue; }
    if (isRow(s) && i+1 < L.length && isSep(L[i+1])) {
      const rows=[]; let j=i;
      while (j < L.length && isRow(L[j])) { rows.push(L[j]); j++; }
      for (let r=0; r<rows.length; r++) {
        if (r===1) continue;
        gRow++;
        const cs = cellsOf(rows[r]);
        for (const c of cs) { const io = inlineOps(c); for (const o of io) ops.push(o); ops.push({ text: '\n', attributes: { table: 'row-'+gRow } }); }
      }
      i=j; continue;
    }
    const t = s.replace(/^\s+/,'');
    let m;
    if (t.charAt(0)==='#') { const h=t.match(/^(#{1,6})\s+(.*)$/); if (h) { emit(inlineOps(h[2]), { header: Math.min(h[1].length,3) }); i++; continue; } }
    if ((m = t.match(/^[-*+]\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'bullet' }); i++; continue; }
    if ((m = t.match(/^\d+\.\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'ordered' }); i++; continue; }
    if (t.charAt(0)==='>') { emit(inlineOps(t.replace(/^>\s?/,'')), { blockquote: true }); i++; continue; }
    if (/^([-*_])\1{2,}$/.test(s.trim())) { i++; continue; }
    if (s.trim()==='') { i++; continue; }
    emit(inlineOps(s), null);
    i++;
  }
  return ops;
}

assembly.sort(function(a,b){ return ((a.order==null?99:a.order) - (b.order==null?99:b.order)); });
const rendered_delta = [];
for (const blk of assembly) {
  if (blk.kind === 'text') {
    for (const op of mdToOps(blk.md || '')) rendered_delta.push(op);
  } else if (blk.kind === 'image') {
    const hit = byPid[blk.placeholder_id];
    if (hit) {
      rendered_delta.push({ type: 'image_ref', placeholder_id: blk.placeholder_id });
      if (blk.caption) rendered_delta.push({ text: blk.caption + '\n', attributes: { italic: true } });
      else rendered_delta.push({ text: '\n' });
    } else {
      rendered_delta.push({ text: '[Obraz niedostepny]\n', attributes: { italic: true } });
    }
  }
}
return [{ json: { rendered_delta: rendered_delta, image_manifest: manifest, total_image_cost_pln: 0, image_models: [], warnings: warnings, clickup_task_id: pb.clickup_task_id || '' } }];
